package com.smartdairy.service; import com.smartdairy.entity.Expense; import com.smartdairy.repository.ExpenseRepository; import java.sql.Date; import java.sql.SQLException; import java.util.List;
public class ExpenseService{private final ExpenseRepository repo=new ExpenseRepository(); public void save(Expense e)throws Exception{validate(e);repo.save(e);} public void update(Expense e)throws Exception{if(e.getId()<=0)throw new IllegalArgumentException("Invalid expense id");validate(e);repo.update(e);} public void delete(int id)throws Exception{repo.delete(id);} public List<Expense> findAll()throws Exception{return repo.findAll();} public List<Expense> findByRange(Date from,Date to)throws Exception{return repo.findByRange(from,to);} private void validate(Expense e){if(e.getAmount()<=0)throw new IllegalArgumentException("Expense amount must be greater than zero");if(e.getExpenseDate()==null)throw new IllegalArgumentException("Expense date is required");}}
